label = [3, 6, 16, 1, 10, 24, 0, 26, 7, 27, 2, 22, 5, 23, 11]
edges = []
for g in range(5):
    for i in range(3):
        for j in range(i+1,3):
            edges.append((g*3+i, g*3+j))
for g in range(4):
    for i in range(3):
        edges.append((g*3+i, (g+1)*3+i))

print(len(set(label))==15, all(0<=x<=27 for x in label))
els = [abs(label[a]-label[b]) for a,b in edges]
print(len(els), len(set(els)), sorted(els))
